%[text:tableOfContents]{"heading":"**目录**"}
%[text] 改进代码，在原脚本基础上增加可复用性（`统一实验分析作图v20.6.0，`工程文件20251208拉取）
%[text] 先做PCA再做distance，是否0-1化和normolize在PCA和distance之间保持一致
% ZScore	将基线均值记为μ，标准差记为σ，计算(F-μ)/σ为归一化数据
% dFdF0	将基线均值记为F0，计算F/F0-1为归一化数据
% log2FdF0	将基线均值记为F0，计算log2(F/F0)为归一化数据
%如果用No_special_operation
MB=TransferLearning.MOpBaseline;
%%
QueryTableL2A=UniExp.ReadQueryTable("\\Data-Server-2\个人数据\杨青宁\202512\PCAandDis.xlsx",'Sheet2')
%%
QueryTableA2L=UniExp.ReadQueryTable("\\Data-Server-2\个人数据\杨青宁\202512\PCAandDis.xlsx",'Sheet3')
%%
%[text] 此节为尝试节选出部分QueryTable
QueryTableNL=QueryTableL2A([1 5 9],:);
QueryTableTA=QueryTableL2A([1 5 9]+2,:);
QueryTableNA=QueryTableA2L([1 5 9],:);
QueryTableTL=QueryTableA2L([1 5 9]+2,:);
%%
GroupNtatsNL=UniExp.NtatsCellStrip(MB.QueryNTATS(QueryTableNL,UniExp.Flags.ZScore,1:24,UniExp.Flags.Median));
GroupNtatsTA=UniExp.NtatsCellStrip(MB.QueryNTATS(QueryTableTA,UniExp.Flags.ZScore,1:24,UniExp.Flags.Median));
GroupNtatsNA=UniExp.NtatsCellStrip(MB.QueryNTATS(QueryTableNA,UniExp.Flags.ZScore,1:24,UniExp.Flags.Median));
GroupNtatsTL=UniExp.NtatsCellStrip(MB.QueryNTATS(QueryTableTL,UniExp.Flags.ZScore,1:24,UniExp.Flags.Median));
%%
QueryTableNL=QueryTableL2A([1 5 9],:)
%%
%[text] 从此开始用
%n = randsample(1:30, 6);
n =[14 17 22 24 25 4];
var1 = string(QueryTableNL.Phase(1))+string(n(:)); % 6×1 string
var2 = repmat(QueryTableNL.Paradigm(1), 6, 1); % 6×1 categorical
var3 = repmat(QueryTableNL.Phase(1), 6, 1); % 6×1 categorical
var4 = n(:); % 6×1 double
QT = table(var1, var2, var3, var4,'VariableNames', {'GroupName','Paradigm','Phase','TrialRI'});
%%
GroupNtats=UniExp.NtatsCellStrip(MB.QueryNTATS(QT,UniExp.Flags.ZScore,1:24,UniExp.Flags.Median));
%%
PcaTable=UniExp.LinearPca(GroupNtats.NTATS,3); %[output:388bf2bd]
PcaLines=PcaTable.Score;SampleRate=8;
Markers=table;
%[text] 关键时点突出显示：
Markers.Index=[3;4;6]*SampleRate;%+1
%[text] 关键时点符号
Markers.Shape=('o^s')';
%[text] 作图
figure; %[output:2d542abc]
Lines=UniExp.SegmentFadePlot(table(permute(PcaLines.Data,[3,1,2]),'VariableNames',"Points"),Markers,PatchArguments={'LineWidth',1}); %[output:2d542abc]
legend(Lines,PcaLines.Dimensions.IndexNames{3},Interpreter='none'); %[output:2d542abc]
xlabel(sprintf('PC1 (%.2g%%)',PcaTable.Explained(1))); %[output:2d542abc]
ylabel(sprintf('PC2 (%.2g%%)',PcaTable.Explained(2))); %[output:2d542abc]
zlabel(sprintf('PC3 (%.2g%%)',PcaTable.Explained(3))); %[output:2d542abc]
title('●0s ▲1s ■3s') %[output:2d542abc]
%%
% n = randsample(1:30, 6);
n =[10 13 19 21 3 7];
var1 =string(QueryTableTA.Phase(1))+string(n(:)); % 6×1 string
var2 = repmat(QueryTableTA.Paradigm(1), 6, 1); % 6×1 categorical
var3 = repmat(QueryTableTA.Phase(1), 6, 1); % 6×1 categorical
var4 = n(:); % 6×1 double
QT = table(var1, var2, var3, var4,'VariableNames', {'GroupName','Paradigm','Phase','TrialRI'});
GroupNtats=UniExp.NtatsCellStrip(MB.QueryNTATS(QT,UniExp.Flags.ZScore,1:24,UniExp.Flags.Median));
PcaTable=UniExp.LinearPca(GroupNtats.NTATS,3); %[output:68da7666]
PcaLines=PcaTable.Score;SampleRate=8;
Markers=table;
Markers.Index=[3;4;6]*SampleRate;%+1
Markers.Shape=('o^s')';
figure; %[output:438e3381]
Lines=UniExp.SegmentFadePlot(table(permute(PcaLines.Data,[3,1,2]),'VariableNames',"Points"),Markers,PatchArguments={'LineWidth',1}); %[output:438e3381]
legend(Lines,PcaLines.Dimensions.IndexNames{3},Interpreter='none'); %[output:438e3381]
xlabel(sprintf('PC1 (%.2g%%)',PcaTable.Explained(1))); %[output:438e3381]
ylabel(sprintf('PC2 (%.2g%%)',PcaTable.Explained(2))); %[output:438e3381]
zlabel(sprintf('PC3 (%.2g%%)',PcaTable.Explained(3))); %[output:438e3381]
title('●0s ▲1s ■3s') %[output:438e3381]
%%
QueryTableLL=QueryTableL2A([1 5 9]+1,:);
% n = randsample(1:30, 6);
n =[10 16 18 3 30 8];
var1 =string(QueryTableLL.Phase(1))+string(n(:)); % 6×1 string
var2 = repmat(QueryTableLL.Paradigm(1), 6, 1); % 6×1 categorical
var3 = repmat(QueryTableLL.Phase(1), 6, 1); % 6×1 categorical
var4 = n(:); % 6×1 double
QT = table(var1, var2, var3, var4,'VariableNames', {'GroupName','Paradigm','Phase','TrialRI'});
GroupNtats=UniExp.NtatsCellStrip(MB.QueryNTATS(QT,UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:322d507c] %[output:1ea56bef] %[output:8514c151] %[output:1c2fd070] %[output:62d5f299] %[output:8e8ac3c2]
PcaTable=UniExp.LinearPca(GroupNtats.NTATS,3); %[output:37329b3c]
PcaLines=PcaTable.Score;SampleRate=8;
Markers=table;
Markers.Index=[3;4;6]*SampleRate;%+1
Markers.Shape=('o^s')';
figure; %[output:4e2ceee7]
Lines=UniExp.SegmentFadePlot(table(permute(PcaLines.Data,[3,1,2]),'VariableNames',"Points"),Markers,PatchArguments={'LineWidth',1}); %[output:4e2ceee7]
legend(Lines,PcaLines.Dimensions.IndexNames{3},Interpreter='none'); %[output:4e2ceee7]
xlabel(sprintf('PC1 (%.2g%%)',PcaTable.Explained(1))); %[output:4e2ceee7]
ylabel(sprintf('PC2 (%.2g%%)',PcaTable.Explained(2))); %[output:4e2ceee7]
zlabel(sprintf('PC3 (%.2g%%)',PcaTable.Explained(3))); %[output:4e2ceee7]
title('●0s ▲1s ■3s') %[output:4e2ceee7]
%%
% n = randsample(1:30, 6);
n=[12 13 18 23 27 8];
var1 =string(QueryTableNA.Phase(1))+string(n(:)); % 6×1 string
var2 = repmat(QueryTableNA.Paradigm(1), 6, 1); % 6×1 categorical
var3 = repmat(QueryTableNA.Phase(1), 6, 1); % 6×1 categorical
var4 = n(:); % 6×1 double
QT = table(var1, var2, var3, var4,'VariableNames', {'GroupName','Paradigm','Phase','TrialRI'});
GroupNtats=UniExp.NtatsCellStrip(MB.QueryNTATS(QT,UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:393d7cd3]
PcaTable=UniExp.LinearPca(GroupNtats.NTATS,3);
PcaLines=PcaTable.Score;SampleRate=8;
Markers=table;
Markers.Index=[3;4;6]*SampleRate;%+1
Markers.Shape=('o^s')';
figure; %[output:3718bfef]
Lines=UniExp.SegmentFadePlot(table(permute(PcaLines.Data,[3,1,2]),'VariableNames',"Points"),Markers,PatchArguments={'LineWidth',1}); %[output:3718bfef]
legend(Lines,PcaLines.Dimensions.IndexNames{3},Interpreter='none'); %[output:3718bfef]
xlabel(sprintf('PC1 (%.2g%%)',PcaTable.Explained(1))); %[output:3718bfef]
ylabel(sprintf('PC2 (%.2g%%)',PcaTable.Explained(2))); %[output:3718bfef]
zlabel(sprintf('PC3 (%.2g%%)',PcaTable.Explained(3))); %[output:3718bfef]
title('●0s ▲1s ■3s') %[output:3718bfef]
%%
%[text] 到此结束

